import './App.css';
import axios from 'axios';
import React, { useState } from 'react';
import CodeBox from './components/code-box';
import QuestionBubble from './components/question-bubble';

function App() {
  // State to hold retrieved problem and code
  const [problemText, setProblemText] = useState('');
  const [codeSnippet, setCodeSnippet] = useState('');
  const [problemNumber, setProblemNumber] = useState(1);

  // Function to fetch the problem
  const fetchProblem = async () => {
    try {
      const response = await axios.get(`http://localhost:5000/problem/${problemNumber}`);
      setProblemText(response.data.code); // Set the problem text
    } catch (error) {
      console.error('Error fetching problem:', error);
      setProblemText('Failed to retrieve problem.');
    }
  };

  // Function to fetch the code
  const fetchCode = async () => {
    try {
      const response = await axios.get(`http://localhost:5000/code/${problemNumber}`);
      setCodeSnippet(response.data.code); // Set the code snippet
    } catch (error) {
      console.error('Error fetching code:', error);
      setCodeSnippet('Failed to retrieve code.');
    }
  };

  return (
    <div className="App">
      <div className="logo-line">
        <img src="logo.jpg" alt="Logo" className="logo-image" />
      </div>
      <div className="content-wrapper">
        <div className="content-line">
          <div className="content-column">
            <div className="form-group">
              <label className="problem-label" htmlFor="problem-number">
                Problem number:
                <input
                  type="number"
                  id="problem-number"
                  name="problem-number"
                  className="problem-input"
                  value={problemNumber}
                  onChange={(e) => setProblemNumber(e.target.value)} // Update problem number dynamically
                />
                <button className="button" onClick={fetchProblem}>
                  Retrieve problem
                </button>
              </label>
            </div>
            <QuestionBubble text={problemText} />
          </div>
          <div className="content-column">
            <CodeBox code={codeSnippet} />
            <button className="button" onClick={fetchCode}>
              Retrieve code and solution
            </button>
          </div>
        </div>
      </div>
      <div className="name-line">
        <p className="name">Created by Lucas Marques Felix</p>
      </div>
    </div>
  );
}

export default App;
